class Solution {
  public int maxDifference(String s, int k) {
    int n = s.length();
    int[][] pre = new int[5][n + 1];
    for (int c = 0; c < 5; c++)
      for (int i = 0; i < n; i++) pre[c][i + 1] = pre[c][i] + (s.charAt(i) - '0' == c ? 1 : 0);
    int INF = Integer.MAX_VALUE / 2, ans = -INF;
    for (int a = 0; a < 5; a++) {
      for (int b = 0; b < 5; b++) {
        if (a == b) continue;
        int[][] best = new int[2][2];
        for (int[] row : best) java.util.Arrays.fill(row, INF);
        int lp = 0;
        for (int r = 1; r <= n; r++) {
          while (lp <= r - k && pre[b][r] - pre[b][lp] >= 2) {
            int pa = pre[a][lp], pb = pre[b][lp];
            best[pa & 1][pb & 1] = Math.min(best[pa & 1][pb & 1], pa - pb);
            lp++;
          }
          int cand = best[(pre[a][r] & 1) ^ 1][pre[b][r] & 1];
          if (cand < INF) ans = Math.max(ans, pre[a][r] - pre[b][r] - cand);
        }
      }
    }
    return ans;
  }
}
